/**
 * Dropzone plus a file list with upload states (`design/components/file-upload.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/file-upload.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input, output } from '@angular/core'

import {
  Icon,
  MEMBER_PROVIDERS,
  Ref,
  agentMember,
  cell,
  derived,
  elementRef,
  focusAfterListRemoval,
  formatBytes,
  gateFiles,
  mountEffect,
  presence,
  setup,
  useMember,
  watchEffect,
  type Each,
  type FileRejection,
} from '@polymorph/angular'
import { useListPresence } from '@polymorph/angular/motion'
import styles from '@polymorph/recipes/controls/file-upload.module.css'
import { FileUploadRow, type FileUploadRowProps } from './FileUploadRow'

export type FileUploadStatus = 'uploading' | 'done' | 'error'

export interface FileUploadItem {
  id: string
  name: string
  size?: number
  status: FileUploadStatus
  progress?: number
  message?: string
}

/** Dropzone plus a file list with upload states: the inputs it takes, by the React member's prop names. */
export interface FileUploadProps {
  /**
   * The native syntax (`.pdf`, `image/*`, `application/pdf`), applied to drops too.
   */
  accept?: string
  'aria-describedby'?: string
  /**
   * Set by FormField. Set it directly only when there is no visible label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  disabled?: boolean
  /**
   * Always controlled, because the list and what happens to it are the app's state.
   */
  files?: FileUploadItem[]
  hint?: string
  invalid?: boolean
  /**
   * The app's size ceiling, in bytes. A file over it never reaches `onFilesAdd`.
   */
  maxSize?: number
  /**
   * All control and announcement text, localized by the application.
   */
  messages?: {
    retry: string
    remove: (name: string) => string
    progress: (name: string) => string
    announcement: (file: FileUploadItem) => string
    formatSize: (bytes: number) => string
  }
  /**
   * When `false`, a drop of several files keeps the first that passes and refuses the rest.
   */
  multiple?: boolean
  /**
   * Set on the hidden picker, for a native form post.
   */
  name?: string
  title?: string
}

/** Dropzone plus a file list with upload states. */
@Component({
  selector: 'pm-file-upload',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Ref, FileUploadRow, Icon],
  // prettier-ignore
  template: `<!-- root -->
<div
[attr.class]="e1()"
[attr.data-state]="e2()"
[attr.data-disabled]="e3()"
[attr.data-invalid]="e4()"
data-member="file-upload"
[pmRef]="root"
><!-- dropzone -->
<button
[attr.class]="e5()"
type="button"
[attr.disabled]="e6()"
[attr.data-state]="e2()"
[attr.data-disabled]="e3()"
[attr.data-invalid]="e4()"
[attr.aria-label]="e7()"
[attr.aria-labelledby]="e8()"
[attr.aria-describedby]="e9()"
[attr.aria-required]="e10()"
[attr.aria-invalid]="e11()"
(click)="h1()"
(dragover)="h2($event)"
(dragleave)="h3($event)"
(drop)="h4($event)"
[pmRef]="zone"
><pm-icon
name="upload"
size="lg"
></pm-icon>
<!-- title -->
<span
[attr.class]="e12()"
>{{ e13() }}</span>
@if (e14()) {<!-- hint -->
<span
[attr.class]="e15()"
>{{ e16() }}</span>}</button>
<!-- picker -->
<input
[attr.class]="e17()"
type="file"
[attr.accept]="e18()"
[attr.multiple]="e19()"
[attr.name]="e20()"
[attr.disabled]="e6()"
tabindex="-1"
(change)="h5($event)"
[pmRef]="picker"
/>
@if (e21()) {<!-- list -->
<ul
[attr.class]="e22()"
[pmRef]="rowList"
>@for (row of e23(); track e24(row)) {<li
pmFileUploadRow
[file]="e25(row)"
[open]="e26(row)"
[size]="e27(row)"
[retryable]="e28()"
[retryLabel]="e29()"
[removeLabel]="e30(row)"
[progressLabel]="e31(row)"
(retry)="h6(row)"
(remove)="h7(row)"
(done)="h8(row)"
></li>}</ul>}
<!-- reader -->
<span
[attr.class]="e32()"
aria-live="polite"
>@for (file of e33(); track e34(file)) {<span>{{ e35(file) }}</span>}</span></div>`,
})
export class FileUpload {
  static readonly controlKind = 'group'
  /**
   * The native syntax (`.pdf`, `image/*`, `application/pdf`), applied to drops too.
   */
  readonly accept = input<FileUploadProps['accept']>(undefined)
  readonly ariaDescribedby = input<FileUploadProps['aria-describedby']>(undefined, {
    alias: 'aria-describedby',
  })
  /**
   * Set by FormField. Set it directly only when there is no visible label.
   */
  readonly ariaLabel = input<FileUploadProps['aria-label']>(undefined, { alias: 'aria-label' })
  readonly ariaLabelledby = input<FileUploadProps['aria-labelledby']>(undefined, {
    alias: 'aria-labelledby',
  })
  readonly ariaRequired = input<FileUploadProps['aria-required']>(undefined, {
    alias: 'aria-required',
  })
  readonly disabled = input<
    Exclude<FileUploadProps['disabled'], undefined>,
    FileUploadProps['disabled']
  >(false, {
    transform: (value: FileUploadProps['disabled']) => (value === undefined ? false : value),
  })
  /**
   * Always controlled, because the list and what happens to it are the app's state.
   */
  readonly files = input<Exclude<FileUploadProps['files'], undefined>, FileUploadProps['files']>(
    (() => [])(),
    {
      transform: (value: FileUploadProps['files']) => (value === undefined ? (() => [])() : value),
    },
  )
  readonly hint = input<FileUploadProps['hint']>(undefined)
  readonly invalid = input<
    Exclude<FileUploadProps['invalid'], undefined>,
    FileUploadProps['invalid']
  >(false, {
    transform: (value: FileUploadProps['invalid']) => (value === undefined ? false : value),
  })
  /**
   * The app's size ceiling, in bytes. A file over it never reaches `onFilesAdd`.
   */
  readonly maxSize = input<FileUploadProps['maxSize']>(undefined)
  /**
   * All control and announcement text, localized by the application.
   */
  readonly messages = input<
    Exclude<FileUploadProps['messages'], undefined>,
    FileUploadProps['messages']
  >(
    (() => ({
      retry: 'Retry',
      remove: (name: string) => `Remove ${name}`,
      progress: (name: string) => `${name} upload progress`,
      announcement: (file: FileUploadItem) =>
        file.status === 'done'
          ? `${file.name} uploaded`
          : file.status === 'error'
            ? file.message === undefined
              ? `${file.name} failed`
              : `${file.name} failed: ${file.message}`
            : '',
      formatSize: formatBytes,
    }))(),
    {
      transform: (value: FileUploadProps['messages']) =>
        value === undefined
          ? (() => ({
              retry: 'Retry',
              remove: (name: string) => `Remove ${name}`,
              progress: (name: string) => `${name} upload progress`,
              announcement: (file: FileUploadItem) =>
                file.status === 'done'
                  ? `${file.name} uploaded`
                  : file.status === 'error'
                    ? file.message === undefined
                      ? `${file.name} failed`
                      : `${file.name} failed: ${file.message}`
                    : '',
              formatSize: formatBytes,
            }))()
          : value,
    },
  )
  /**
   * When `false`, a drop of several files keeps the first that passes and refuses the rest.
   */
  readonly multiple = input<
    Exclude<FileUploadProps['multiple'], undefined>,
    FileUploadProps['multiple']
  >(true, {
    transform: (value: FileUploadProps['multiple']) => (value === undefined ? true : value),
  })
  /**
   * Set on the hidden picker, for a native form post.
   */
  readonly name = input<FileUploadProps['name']>(undefined)
  readonly title = input<Exclude<FileUploadProps['title'], undefined>, FileUploadProps['title']>(
    'Drop files or click to browse',
    {
      transform: (value: FileUploadProps['title']) =>
        value === undefined ? 'Drop files or click to browse' : value,
    },
  )
  /**
   * Only files that passed the gate (`accept`, `maxSize`, `multiple`), from the picker or a
   * drop.
   */
  readonly onFilesAdd = output<File[]>({ alias: 'filesAdd' })
  /**
   * The counterpart of `onFilesAdd`: every file the gate refused, and why. `file-upload.md`
   * requires a rejection to be "a *visible row*, never a silent drop", and rows only come from
   * `files`, which the app owns. So the component refuses the file and returns it with a reason,
   * and the app renders the refusal as an `error` row in its own words. **Required.** If it were
   * optional, the spec's main guarantee would be optional too. A field that sets `maxSize` and
   * passes no `onReject` would silently drop an oversized file, with no row, no message and no
   * event, and the user would see a chosen file fail to appear. The component cannot write the
   * row itself, because the text and the list belong to the app, and it must not hide the
   * refusal. So the handler is required.
   */
  readonly onReject = output<FileRejection[]>({ alias: 'reject' })
  readonly onRemove = output<string>({ alias: 'remove' })
  /**
   * When supplied, `error` rows offer a retry.
   */
  readonly onRetry = output<string>({ alias: 'retry' })
  protected readonly $ = useMember({
    kind: FileUpload.controlKind,
    events: ['filesAdd', 'reject', 'remove', 'retry'],
    props: {
      accept: () => this.accept(),
      'aria-describedby': () => this.ariaDescribedby(),
      'aria-label': () => this.ariaLabel(),
      'aria-labelledby': () => this.ariaLabelledby(),
      'aria-required': () => this.ariaRequired(),
      disabled: () => this.disabled(),
      files: () => this.files(),
      hint: () => this.hint(),
      invalid: () => this.invalid(),
      maxSize: () => this.maxSize(),
      messages: () => this.messages(),
      multiple: () => this.multiple(),
      name: () => this.name(),
      title: () => this.title(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly dragover = cell(() => false)
  protected readonly pressed = cell(() => null as { id: string; at: number } | null)
  protected readonly picker = elementRef<HTMLElement>()
  protected readonly root = elementRef<HTMLElement>()
  protected readonly rowList = elementRef<HTMLElement>()
  protected readonly zone = elementRef<HTMLElement>()
  protected readonly zoneState = derived(() => (this.dragover.value ? 'dragover' : 'idle'))
  protected readonly rowOf = derived(
    () => (id: string | undefined) =>
      id === undefined
        ? null
        : (this.rowList.value?.children[this.rows.value().findIndex((row) => row.key === id)] ??
          null),
  )
  protected readonly removeControl = derived(
    () => (row: Element | null) =>
      row === null ? null : ([...row.querySelectorAll<HTMLElement>('button')].pop() ?? null),
  )
  protected readonly add = derived(
    () => (list: FileList | null | undefined) =>
      !this.$p.disabled &&
      list != null &&
      list.length > 0 &&
      ((gate) => (
        gate.accepted.length > 0 && this.$.emit(this.onFilesAdd, 'onFilesAdd', gate.accepted),
        gate.rejected.length > 0 && this.$.emit(this.onReject, 'onReject', gate.rejected)
      ))(
        gateFiles(Array.from(list), {
          accept: this.$p.accept,
          multiple: this.$p.multiple,
          maxSize: this.$p.maxSize,
        }),
      ),
  )
  protected readonly rows = setup(() =>
    useListPresence(
      () => this.$p.files,
      (file: FileUploadItem) => file.id,
    ),
  )
  private release2: (() => void) | undefined

  constructor() {
    watchEffect(
      () => this.$p.files,
      () => this.effect1(),
      false,
    )
    inject(DestroyRef).onDestroy(() => this.release2?.())
    mountEffect(() => this.effect2())
  }

  protected e1() {
    return styles.root
  }

  protected e2() {
    return this.zoneState.value
  }

  protected e3() {
    return this.$p.disabled ? '' : undefined
  }

  protected e4() {
    return this.$p.invalid ? '' : undefined
  }

  protected e5() {
    return styles.zone
  }

  protected e6() {
    return presence(this.$p.disabled)
  }

  protected e7() {
    return this.$p['aria-label']
  }

  protected e8() {
    return this.$p['aria-labelledby']
  }

  protected e9() {
    return this.$p['aria-describedby']
  }

  protected e10() {
    return this.$p['aria-required']
  }

  protected e11() {
    return this.$p.invalid ? true : undefined
  }

  protected h1(): void {
    this.picker.value?.click()
  }

  protected h2($event: DragEvent): void {
    void ($event.preventDefault(), !this.$p.disabled && (this.dragover.value = true))
  }

  protected h3($event: DragEvent): void {
    if (!($event.currentTarget as HTMLElement).contains($event.relatedTarget as Node | null)) {
      this.dragover.value = false
    }
  }

  protected h4($event: DragEvent): void {
    void ($event.preventDefault(),
    (this.dragover.value = false),
    this.add.value($event.dataTransfer?.files))
  }

  protected e12() {
    return styles.title
  }

  protected e13() {
    return this.$p.title
  }

  protected e14() {
    return this.$p.hint !== undefined
  }

  protected e15() {
    if (!(this.$p.hint !== undefined)) return undefined as never
    return styles.hint
  }

  protected e16() {
    if (!(this.$p.hint !== undefined)) return undefined as never
    return this.$p.hint
  }

  protected e17() {
    return styles.picker
  }

  protected e18() {
    return this.$p.accept
  }

  protected e19() {
    return presence(this.$p.multiple)
  }

  protected e20() {
    return this.$p.name
  }

  protected h5($event: Event): void {
    void (this.add.value(($event.target as HTMLInputElement).files),
    (($event.target as HTMLInputElement).value = ''))
  }

  protected e21() {
    return this.$p.files.length > 0
  }

  protected e22() {
    if (!(this.$p.files.length > 0)) return undefined as never
    return styles.list
  }

  e23() {
    if (!(this.$p.files.length > 0)) return undefined as never
    return this.rows.value()
  }

  protected e24(row: Each<ReturnType<FileUpload['e23']>>) {
    return row.key
  }

  protected e25(row: Each<ReturnType<FileUpload['e23']>>): FileUploadRowProps['file'] {
    if (!(this.$p.files.length > 0)) return undefined as never
    return row.item
  }

  protected e26(row: Each<ReturnType<FileUpload['e23']>>): FileUploadRowProps['open'] {
    if (!(this.$p.files.length > 0)) return undefined as never
    return row.open
  }

  protected e27(row: Each<ReturnType<FileUpload['e23']>>): FileUploadRowProps['size'] {
    if (!(this.$p.files.length > 0)) return undefined as never
    return row.item.size === undefined ? undefined : this.$p.messages.formatSize(row.item.size)
  }

  protected e28(): FileUploadRowProps['retryable'] {
    if (!(this.$p.files.length > 0)) return undefined as never
    return this.$.listening(this.onRetry, 'onRetry') === true
  }

  protected e29(): FileUploadRowProps['retryLabel'] {
    if (!(this.$p.files.length > 0)) return undefined as never
    return this.$p.messages.retry
  }

  protected e30(row: Each<ReturnType<FileUpload['e23']>>): FileUploadRowProps['removeLabel'] {
    if (!(this.$p.files.length > 0)) return undefined as never
    return this.$p.messages.remove(row.item.name)
  }

  protected e31(row: Each<ReturnType<FileUpload['e23']>>): FileUploadRowProps['progressLabel'] {
    if (!(this.$p.files.length > 0)) return undefined as never
    return this.$p.messages.progress(row.item.name)
  }

  protected h6(row: Each<ReturnType<FileUpload['e23']>>): void {
    if (!(this.$p.files.length > 0)) return
    this.$.emit(this.onRetry, 'onRetry', row.item.id)
  }

  protected h7(row: Each<ReturnType<FileUpload['e23']>>): void {
    if (!(this.$p.files.length > 0)) return
    void ((this.pressed.value = {
      id: row.item.id,
      at: this.$p.files.findIndex((file) => file.id === row.item.id),
    }),
    this.$.emit(this.onRemove, 'onRemove', row.item.id))
  }

  protected h8(row: Each<ReturnType<FileUpload['e23']>>): void {
    if (!(this.$p.files.length > 0)) return
    row.done()
  }

  protected e32() {
    return styles.reader
  }

  e33() {
    return this.$p.files
  }

  protected e34(file: Each<ReturnType<FileUpload['e33']>>) {
    return file.id
  }

  protected e35(file: Each<ReturnType<FileUpload['e33']>>) {
    return this.$p.messages.announcement(file)
  }

  private effect1(): void {
    this.pressed.value = focusAfterListRemoval(
      this.pressed.value,
      this.$p.files.map((file) => file.id),
      (at) => this.removeControl.value(this.rowOf.value(this.$p.files[at]?.id)),
      this.zone.value,
      this.pressed.value === null ? null : this.rowOf.value(this.pressed.value.id),
    )
  }

  private effect2(): void {
    this.release2?.()
    const ran = agentMember({
      member: 'FileUpload',
      element: () => this.zone.value,
      state: () => ({
        files: this.$p.files.map((file) => ({ ...file })),
        rows: this.$p.files.map((file) => ({ id: file.id, label: file.name })),
        disabled: this.$p.disabled,
        invalid: this.$p.invalid,
      }),
      actions: {
        remove: { argument: 'id', run: (value) => this.$.emit(this.onRemove, 'onRemove', value) },
        retry: {
          argument: 'id',
          run: (value) =>
            (() => {
              if (this.$.listening(this.onRetry, 'onRetry') !== true)
                throw new Error('The field offers no retry.')
              if (this.$p.files.find((file) => file.id === value)?.status !== 'error')
                throw new Error('Only a failed upload is retried.')
              this.$.emit(this.onRetry, 'onRetry', value)
            })(),
        },
      },
      withholds: () => this.root.value,
    })
    this.release2 = () => {
      ran()
    }
  }
}
